"""Actual Word bytes are unit witnesses, never physical acceptance receipts."""
import base64,copy,gzip,importlib.util,json,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
spec=importlib.util.spec_from_file_location('m',ROOT/'scripts/ops/rtk-interop-word-manuscript-readback.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
# Owned C1 Word source run, 2026-09-25. Retained unchanged; no provider rerun in tests.
RAW={k:base64.b64decode(v) for k,v in json.loads(gzip.decompress(base64.b64decode(''))).items()}
class MediaOracle(unittest.TestCase):
 def setUp(self):
  self.docs=m.expected_docs('SINGLE_SCENE','C1',recipe='MEDIA_V1');self.graph=m.media.canonical_graph(self.docs)
  self.ps,self.parts,self.doc=m.docx(RAW['rounds/1/returned.docx'],media_profile=True)
 def test_actual_word_bytes_and_six_independent_corruptions(self):
  self.assertEqual(m.media.package_graph(self.parts,self.doc),self.graph)
  controls=m.media.negative_controls(self.parts,self.doc,self.graph)
  self.assertEqual([c['id'] for c in controls],m.media.CONTROLS)
  self.assertEqual(len({c['sha256'] for c in controls}),6)
  self.assertTrue(all(c['rejected'] for c in controls))
  with self.assertRaisesRegex(ValueError,'DOCX_RUN'):m.docx(RAW['rounds/1/returned.docx'])
 def test_native_objects_bind_literal_alt_position_and_full_body(self):
  body=RAW['rounds/1/word/word-native-readback.txt'];index=RAW['rounds/1/word/word-media.tsv']
  read=lambda f:RAW['rounds/1/word/'+f]
  self.assertEqual(m.v.native(m.media.native_body(body,index,read,self.graph,self.ps)),self.ps)
  for kind in ['body-marker','count','size','offset','alt']:
   b=body;idx=index;rd=read
   if kind=='body-marker':b=b.replace(b'/',b'!',1)
   elif kind=='count':idx=idx.replace(b'3\n',b'2\n',1)
   elif kind=='size':idx=idx.replace(b'120,0',b'121,0',1)
   elif kind=='offset':idx=idx.replace(b'1323',b'1324',1)
   else:rd=lambda f:b'changed'
   with self.subTest(kind=kind),self.assertRaises(ValueError):m.media.native_body(b,idx,rd,self.graph,self.ps)
 def test_retained_deletion_coordinate_is_distinct_from_accepted_text(self):
  graph=[{**self.graph[0],'paragraphIndex':1,'offset':2}]
  d=m.ET.fromstring(('<w:document xmlns:w="'+m.W[1:-1]+'"><w:body><w:p><w:del><w:r><w:delText>sentinel alpha</w:delText></w:r></w:del></w:p><w:p><w:r><w:drawing/></w:r></w:p></w:body></w:document>').encode())
  deleted=m.media.deleted_prefixes(d);self.assertEqual(deleted,[14])
  ps=['sentinel round1','x y'];start=m.media.u16(ps[0])+1+2
  idx=f'1\n1\t120,0\t60,0\t{start+14}\t{start+15}\n'.encode();body=b'sentinel round1\rx /y\r'
  rd=lambda f:graph[0]['alt'].encode()
  self.assertEqual(m.v.native(m.media.native_body(body,idx,rd,graph,ps,deleted=deleted)),ps)
  with self.assertRaises(ValueError):m.media.native_body(body,idx,rd,graph,ps)
 def test_png_and_canonical_tampering_cannot_preserve_media_proof(self):
  data=base64.b64decode(m.media.ENCODED[0]);self.assertEqual(m.media.png(data)['sha256'],m.media.HASHES[0])
  for b in [data[:-1],data+b'x',data[:30]+bytes([data[30]^1])+data[31:],b'\x89PNG\r\n\x1a\n'+b'x'*100]:
   with self.assertRaises((ValueError,m.media.zlib.error)):m.media.png(b)
  for key,value in [('assetPath','../image.png'),('sha256',m.media.HASHES[1]),('alt','changed'),('width',1),('dataBase64',m.media.ENCODED[1])]:
   docs=copy.deepcopy(self.docs);image=next(c for p in docs[0]['content'] for c in p.get('content',[]) if c.get('type')=='image');image['attrs'][key]=value
   with self.subTest(key=key),self.assertRaises(ValueError):m.media.canonical_graph(docs)
 def test_renderer_hidden_reused_image_is_a_blocking_failure(self):
  rows=[{'index':i,'src':'data:image/png;base64,'+m.media.ENCODED[m.media.HASHES.index(g['sha256'])],'alt':g['alt'],'width':160,'height':80,'naturalWidth':160,'naturalHeight':80,'hit':True,'display':'inline','visibility':'visible','opacity':'1'} for i,g in enumerate(self.graph)]
  m.media.renderer(rows,self.graph,views=True)
  for change in [{'hit':False},{'visibility':'hidden'},{'naturalWidth':0},{'src':'https://example.invalid/img'}]:
   changed=copy.deepcopy(rows);changed[-1].update(change)
   with self.assertRaises(ValueError):m.media.renderer(changed,self.graph,views=True)
 def test_fixed_24_cells_keep_route_and_profile_boundaries(self):
  ids=[]
  for volume in ['SINGLE_SCENE','MULTI_SCENE','FULL_SYNTHETIC_NOVEL','LARGE_DOCUMENT']:
   for route in ['C1','C2','C3']:
    self.assertEqual(m.fields(volume,route,'MEDIA_V1'),['MEDIA_ASSETS'])
    graph=m.media.canonical_graph(m.expected_docs(volume,route,recipe='MEDIA_V1'));self.assertEqual(len(graph),3)
    self.assertEqual(len({g['sha256'] for g in graph}),2)
    for profile in ['SOURCE_RUNTIME','PACKAGED_BUILD_RUNTIME']:ids.append(f'MEDIA_ASSETS__{volume}__{route}__{profile}')
  self.assertEqual(len(set(ids)),24)
  with self.assertRaises(ValueError):m.fields('SINGLE_SCENE','C5','MEDIA_V1')
if __name__=='__main__':unittest.main()
